/**
 * Realistic sample data for galleries and tests (generated by tools/oracle/viewer_mockdata.py
 * from public plasmid records). Enzyme sites here are approximate and only for visual
 * development: real sites come from @hhereditas/core.
 */
import type { EnzymeSite, SeqRecord } from '@hhereditas/core';
import pBAD30 from './__fixtures__/pBAD30.json';
import pBR322 from './__fixtures__/pBR322.json';
import pFA6a from './__fixtures__/pFA6a-kanMX6.json';
import linear11664 from './__fixtures__/addgene-11664-linear.json';

export interface SampleData {
  record: SeqRecord;
  enzymeSites: EnzymeSite[];
}

function asSample(data: unknown): SampleData {
  return data as SampleData;
}

export const SAMPLES = {
  /** 3,938 bp circular yeast deletion plasmid; has a promoter spanning the origin. */
  pFA6a: asSample(pFA6a),
  /** 4,923 bp circular E. coli expression vector. */
  pBAD30: asSample(pBAD30),
  /** 4,361 bp circular classic vector with many (dense, overlapping) annotations. */
  pBR322: asSample(pBR322),
  /** 8,596 bp LINEAR record with many features. */
  linear: asSample(linear11664),
} as const;

export type SampleName = keyof typeof SAMPLES;
